SELECT c.*, v.venue_name, (SELECT COUNT(*) FROM booking b WHERE b.court_id = c.court_id) AS total_bookings FROM court c JOIN venue v ON v.venue_id = c.venue_id
AND c.operational_status = #{status}
AND c.venue_id = #{venueId}
ORDER BY c.court_id ASC

SELECT COUNT(*)
FROM booking
WHERE court_id = #{courtId}
  AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'IN_PROGRESS')
  AND end_at > #{now}
